import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import DiscussionControls from 'flarum/forum/utils/DiscussionControls';

/**
 * Telefonda ekranın altında sabit duran 5 sekmeli gezinme çubuğu
 * (Akış · Keşfet · Yükle · Bildirimler · Profil). Masaüstünde CSS ile gizlidir.
 */
export default class MobileTabBar extends Component {
  view() {
    // Düzenleyici açıkken çubuk gizlenir; düzenleyici tüm ekranı kullanır
    if (app.composer && app.composer.isVisible && app.composer.isVisible()) return m("nav", {
      className: "MobileTabBar-hidden"
    });
    const user = app.session.user;
    const route = app.current.get('routeName');

    // Mesaj sayfası (Threads düzeni): alt çubuk yerine sabit yanıt kutusu
    const discussion = app.current.get('discussion');
    if (discussion && /^discussion/.test(route || '')) {
      document.documentElement.classList.remove('MobileRoot');
      return m("div", {
        className: "MobileTabBar-wrap"
      }, m("div", {
        className: "MobileReplyBar"
      }, m("button", {
        type: "button",
        className: "MobileReplyBar-back",
        "aria-label": "Geri",
        onclick: () => window.history.length > 1 ? window.history.back() : this.go('/all?sort=feed')
      }, m("i", {
        className: "icon fas fa-chevron-left"
      })), m("button", {
        type: "button",
        className: "MobileReplyBar-input",
        onclick: () => this.reply(discussion)
      }, user ? user.displayName() + ' olarak yanıtla…' : 'Yanıtlamak için giriş yap'), m("button", {
        type: "button",
        className: "MobileReplyBar-send",
        onclick: () => this.reply(discussion)
      }, "Yan\u0131tla")));
    }
    const unread = user ? user.unreadNotificationCount() || 0 : 0;
    const tab = (key, ic, label, active, onclick, badge) => m("button", {
      type: "button",
      className: 'MobileTabBar-tab' + (active ? ' active' : '') + (key === 'upload' ? ' MobileTabBar-upload' : ''),
      "aria-label": label,
      onclick: onclick
    }, m("i", {
      className: 'icon ' + ic,
      "aria-hidden": "true"
    }), badge ? m("span", {
      className: "MobileTabBar-badge"
    }, badge > 9 ? '9+' : badge) : null);
    return m("div", {
      className: "MobileTabBar-wrap"
    }, this.rootLogo(route), m("button", {
      type: "button",
      className: 'MobileHeaderBell' + (route === 'notifications' ? ' active' : ''),
      "aria-label": "Bildirimler",
      onclick: () => user ? this.go(app.route('notifications')) : this.login()
    }, m("i", {
      className: "icon fas fa-bell",
      "aria-hidden": "true"
    }), unread ? m("span", {
      className: "MobileTabBar-badge"
    }, unread > 9 ? '9+' : unread) : null), m("nav", {
      className: "MobileTabBar",
      "aria-label": "Alt gezinme"
    }, tab('home', 'fas fa-house', 'Akış', m.route.get() === '/all?sort=feed' || route === 'tags', () => this.go('/all?sort=feed')), tab('explore', 'fas fa-compass', 'Keşfet', route === 'framio.explore', () => this.go(app.route('framio.explore'))), tab('upload', 'fas fa-plus', 'Fotoğraf paylaş', false, () => this.upload()), tab('cats', 'fas fa-layer-group', 'Kategoriler', route === 'framio.categories' || route === 'tag', () => this.go('/kategoriler')), tab('profile', 'fas fa-user', 'Profil', route && route.indexOf('user') === 0, () => user ? this.go(app.route.user(user)) : this.login())));
  }

  // Ana sekmelerde (Akış, Keşfet, Kategoriler, ana sayfa, kategori) başlıkta geri oku yerine logo
  rootLogo(route) {
    const root = ['index', 'tags', 'tag', 'framio.explore', 'framio.categories'].includes(route);
    document.documentElement.classList.toggle('MobileRoot', root);
    if (route !== 'tag') document.documentElement.classList.remove('MobileTagPage');
    const logo = app.forum.attribute('logoUrl');
    if (!root || !logo) return null;
    return m("a", {
      href: app.forum.attribute('baseUrl'),
      className: "MobileHeaderLogo",
      onclick: e => {
        e.preventDefault();
        this.go('/all?sort=feed');
      }
    }, m("img", {
      src: logo,
      alt: app.forum.attribute('title')
    }));
  }
  reply(discussion) {
    if (!app.session.user) return this.login();
    const r = DiscussionControls.replyAction.call(discussion, true, false);
    if (r && r.catch) r.catch(() => {});
  }
  go(url) {
    if (m.route.get() === url) window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });else m.route.set(url);
  }
  login() {
    flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal').then(mod => app.modal.show(mod.default));
  }
  upload() {
    if (!app.session.user) return this.login();
    // Yeni başlık düzenleyicisini açar (fotoğraf yükleme düğmesi düzenleyicinin içindedir)
    flarum.reg.asyncModuleImport('flarum/forum/components/DiscussionComposer').then(mod => {
      app.composer.load(mod.default, {
        user: app.session.user
      });
      app.composer.show();
    });
  }
}
flarum.reg.add('framio-custom-homepage', 'forum/components/MobileTabBar', MobileTabBar);